#!/usr/bin/env python3
"""Claude Code PreToolUse hook: generated code is never edited by hand."""

import json
import sys

GENERATED = {
    "/src/shared/api/generated/": "Generated by Orval: run `npm run generate:api` "
                                  "(running backend or OPENAPI_URL=../backend/openapi.json). "
                                  "To change the contract, change the backend endpoint/schema.",
    "/src/routeTree.gen.ts": "Generated by TanStack Router from src/routes "
                             "(on `npm run dev` / `npm run build`).",
}


def main():
    payload = json.load(sys.stdin)
    path = payload.get("tool_input", {}).get("file_path", "")
    for marker, reason in GENERATED.items():
        if marker in path:
            print(json.dumps({
                "hookSpecificOutput": {
                    "hookEventName": "PreToolUse",
                    "permissionDecision": "deny",
                    "permissionDecisionReason": "Generated file, do not edit. " + reason,
                }
            }, ensure_ascii=False))
            return


if __name__ == "__main__":
    main()
